#include "log.h"
#include <condition_variable>
#include <functional>
#include <list>
#include <mutex>
#include <optional>
#include <thread>

namespace ws {

class ThreadPool {
public:
    using Task = std::function<void()>;

    explicit ThreadPool(std::optional<std::size_t> thread_count = std::nullopt, log::Logger::Ptr logger = log::RootLogger()) noexcept;
    ~ThreadPool() noexcept;

    ThreadPool(const ThreadPool&) = delete;
    ThreadPool& operator=(const ThreadPool&) = delete;
    ThreadPool(ThreadPool&&) = delete;
    ThreadPool& operator=(ThreadPool&&) = delete;

    void Start() noexcept;
    void Push(Task task) noexcept;
    void Close() noexcept;

private:
    void ExecProc() noexcept;

    log::Logger::Ptr logger_;
    std::mutex mtx_;
    bool closed_;
    std::size_t thread_count_;
    std::condition_variable cond_;
    std::list<Task> tasks_;
    std::list<std::thread> threads_;
};

ThreadPool::ThreadPool(std::optional<std::size_t> thread_count = std::nullopt, log::Logger::Ptr logger = log::RootLogger()) noexcept
    : logger_(logger), closed_(false) {
    if (!thread_count.has_value()) {
        thread_count_ = std::thread::hardware_concurrency();
    } else {
        thread_count_ = *thread_count;
    }
}

ThreadPool::~ThreadPool() noexcept {
    Close();
    for (auto& thread : threads_) {
        if (thread.joinable()) {
            thread.join();
        }
    }
}

void ThreadPool::Start() noexcept {
    if (!threads_.empty()) {
        return;
    }
    for (std::size_t i = 0; i < thread_count_; ++i) {
        threads_.emplace_back(&ThreadPool::ExecProc, this);
    }
}

void ThreadPool::Push(Task task) noexcept {
    if (closed_) {
        return;
    }
    std::lock_guard<std::mutex> lock(mtx_);
    tasks_.push_back(task);
    cond_.notify_one();
}

void ThreadPool::Close() noexcept {
    {
        std::lock_guard<std::mutex> lock(mtx_);
        closed_ = true;
    }
    cond_.notify_all();
}

void ThreadPool::ExecProc() noexcept {
    auto not_empty_or_closed = [this]() -> bool {
        return !tasks_.empty() || closed_;
    };
    while (true) {
        std::unique_lock<std::mutex> lock(mtx_);
        cond_.wait(lock, not_empty_or_closed);
        if (closed_ && tasks_.empty()) {
            break;
        }
        Task task = std::move(tasks_.front());
        tasks_.pop_front();
        lock.unlock();
        try {
            task();
        } catch (const std::exception& e) {
            logger_->Log(log::LogLevel::Error, "Task failed: " + std::string(e.what()));
        }
    }
}

}

